import 'dart:math' as math;
import 'dart:typed_data';

import 'package:flutter/services.dart' show AssetBundle, rootBundle;

/// Asset with the English word list: one `word count` per line, lowercase,
/// most frequent first (see docs/htr-model-notes.md for the source).
const String lexiconAsset = 'assets/htr/word_freq.txt';

/// Asset with study vocabulary the general list misses or ranks too low
/// (neuroscience, psychology, biology, physics ...), same format; generated by
/// `docs/htr_bench/make_subject_words.py`. Merged into the bundled lexicon.
const String subjectWordsAsset = 'assets/htr/subject_words.txt';

// Rows of the edit-distance table, reused across calls: the BK-tree search
// computes tens of thousands of distances per word.
Int32List _rowA = Int32List(64);
Int32List _rowB = Int32List(64);

/// Plain Levenshtein distance (insert, delete, substitute all cost 1).
int levenshtein(String a, String b) {
  if (a == b) return 0;
  if (a.isEmpty) return b.length;
  if (b.isEmpty) return a.length;
  if (b.length + 1 > _rowA.length) {
    _rowA = Int32List(b.length + 1);
    _rowB = Int32List(b.length + 1);
  }
  var prev = _rowA;
  var cur = _rowB;
  for (var j = 0; j <= b.length; j++) {
    prev[j] = j;
  }
  for (var i = 1; i <= a.length; i++) {
    cur[0] = i;
    final ca = a.codeUnitAt(i - 1);
    for (var j = 1; j <= b.length; j++) {
      final sub = prev[j - 1] + (ca == b.codeUnitAt(j - 1) ? 0 : 1);
      final del = prev[j] + 1;
      final ins = cur[j - 1] + 1;
      cur[j] = sub < del ? (sub < ins ? sub : ins) : (del < ins ? del : ins);
    }
    final tmp = prev;
    prev = cur;
    cur = tmp;
  }
  return prev[b.length];
}

/// Letter pairs a recogniser often mixes up in handwriting; replacing one by
/// the other is cheaper than an arbitrary substitution.
const List<String> _confusablePairs = [
  'ao', 'ou', 'oe', 'ec', 'ea', 'nu', 'nr', 'nm', 'mw', 'uv', 'vw', 'vy',
  'il', 'lt', 'it', 'fl', 'ft', 'hb', 'hk', 'gq', 'gy', 'pq', 'ij', 'cl',
  'ds', 'rs', 'sz', 'xz', 'kx', 'lk', 'ck', 'ra', 'rn', 'bd', 'dl', 'sa',
  'nh', 'rv',
];

final Set<int> _confusable = {
  for (final p in _confusablePairs) ...[
    p.codeUnitAt(0) * 256 + p.codeUnitAt(1),
    p.codeUnitAt(1) * 256 + p.codeUnitAt(0),
  ],
};

/// Letters that are thin strokes in handwriting and so often get lost.
const String _narrowLetters = 'iltjf';

/// Edit distance weighted for handwriting: confusable letters substitute for
/// 0.6, narrow letters insert/delete for 0.8, everything else costs 1.
double weightedEditDistance(String a, String b) {
  if (a == b) return 0;
  double indel(int unit) => _narrowLetters.contains(String.fromCharCode(unit)) ? 0.8 : 1.0;
  var prev = List<double>.filled(b.length + 1, 0);
  for (var j = 1; j <= b.length; j++) {
    prev[j] = prev[j - 1] + indel(b.codeUnitAt(j - 1));
  }
  var cur = List<double>.filled(b.length + 1, 0);
  for (var i = 1; i <= a.length; i++) {
    final ca = a.codeUnitAt(i - 1);
    cur[0] = prev[0] + indel(ca);
    for (var j = 1; j <= b.length; j++) {
      final cb = b.codeUnitAt(j - 1);
      final double subCost = ca == cb
          ? 0
          : (_confusable.contains(ca * 256 + cb) ? 0.6 : 1.0);
      cur[j] = math.min(
        prev[j - 1] + subCost,
        math.min(prev[j] + indel(ca), cur[j - 1] + indel(cb)),
      );
    }
    final tmp = prev;
    prev = cur;
    cur = tmp;
  }
  return prev[b.length];
}

/// Letter groups that look like one letter in handwriting: an `m` read
/// where `in` was written (the i-dot lost, three humps), `cl` for `d`, ...
/// Used by [handwritingDistance] only (the decoder keeps its own costs).
const List<(String, String)> _lookAlikeGroups = [
  ('m', 'in'), ('m', 'ni'), ('m', 'rn'), ('m', 'nn'), ('m', 'iu'), ('m', 'ui'),
  ('w', 'uu'), ('w', 'vv'), ('w', 'iu'), ('d', 'cl'), ('h', 'li'), ('h', 'lr'),
  ('k', 'lc'), ('k', 'ic'), ('u', 'ii'), ('n', 'ri'), ('n', 'ii'), ('a', 'ci'),
];

/// How different an observed (recognised) word [a] is from a dictionary
/// word [b], counting what handwriting recognition gets wrong as cheaper:
/// look-alike letters substitute for 0.6 (`n`/`m`, `e`/`c`, `a`/`o` ...),
/// look-alike letter groups for 0.5 (`m` for `in`, `cl` for `d`), thin
/// letters (`i l t j f`) go missing for 0.8, swapping two neighbouring
/// letters costs 1, anything else 1.
double handwritingDistance(String a, String b) {
  if (a == b) return 0;
  final n = a.length, m = b.length;
  double indel(int unit) => _narrowLetters.contains(String.fromCharCode(unit)) ? 0.8 : 1.0;
  final w = m + 1;
  final d = List<double>.filled((n + 1) * w, 0);
  for (var i = 1; i <= n; i++) {
    d[i * w] = d[(i - 1) * w] + indel(a.codeUnitAt(i - 1));
  }
  for (var j = 1; j <= m; j++) {
    d[j] = d[j - 1] + indel(b.codeUnitAt(j - 1));
  }
  for (var i = 1; i <= n; i++) {
    final ca = a.codeUnitAt(i - 1);
    for (var j = 1; j <= m; j++) {
      final cb = b.codeUnitAt(j - 1);
      final sub = ca == cb ? 0.0 : (_confusable.contains(ca * 256 + cb) ? 0.6 : 1.0);
      var v = math.min(
        d[(i - 1) * w + j - 1] + sub,
        math.min(d[(i - 1) * w + j] + indel(ca), d[i * w + j - 1] + indel(cb)),
      );
      if (i > 1 && j > 1 && ca == b.codeUnitAt(j - 2) && a.codeUnitAt(i - 2) == cb) {
        v = math.min(v, d[(i - 2) * w + j - 2] + 1.0);
      }
      for (final (one, two) in _lookAlikeGroups) {
        // One letter of [a] read for two of [b] ...
        if (j > 1 && a[i - 1] == one && b.substring(j - 2, j) == two) {
          v = math.min(v, d[(i - 1) * w + j - 2] + 0.5);
        }
        // ... or two letters of [a] for one of [b].
        if (i > 1 && b[j - 1] == one && a.substring(i - 2, i) == two) {
          v = math.min(v, d[(i - 2) * w + j - 1] + 0.5);
        }
      }
      d[i * w + j] = v;
    }
  }
  return d[n * w + m];
}

/// Optimal-string-alignment (restricted Damerau-Levenshtein) distance: like
/// [levenshtein], but swapping two neighbouring letters (`Nuerons` ->
/// `Neurons`) costs 1 instead of 2.
int damerauLevenshtein(String a, String b) {
  if (a == b) return 0;
  if (a.isEmpty) return b.length;
  if (b.isEmpty) return a.length;
  final w = b.length + 1;
  final d = List<int>.filled((a.length + 1) * w, 0);
  for (var i = 0; i <= a.length; i++) {
    d[i * w] = i;
  }
  for (var j = 0; j <= b.length; j++) {
    d[j] = j;
  }
  for (var i = 1; i <= a.length; i++) {
    for (var j = 1; j <= b.length; j++) {
      final cost = a.codeUnitAt(i - 1) == b.codeUnitAt(j - 1) ? 0 : 1;
      var v = math.min(
        d[(i - 1) * w + j - 1] + cost,
        math.min(d[(i - 1) * w + j] + 1, d[i * w + j - 1] + 1),
      );
      if (i > 1 &&
          j > 1 &&
          a.codeUnitAt(i - 1) == b.codeUnitAt(j - 2) &&
          a.codeUnitAt(i - 2) == b.codeUnitAt(j - 1)) {
        v = math.min(v, d[(i - 2) * w + j - 2] + 1);
      }
      d[i * w + j] = v;
    }
  }
  return d[a.length * w + b.length];
}

// Contractions that people write without the apostrophe, as (plain, full,
// ln probability). The word list has none of them (it is lowercase letters
// plus a few apostrophes, and "don't" sits at rank 40k), so the decoder takes
// their priors from here: the first tier is about as frequent as a top-300
// word, the last about a top-3000 word, which is what they are in notes and
// chat-style writing. Forms that are also ordinary words (its, were, well, ill,
// id, hell, shell, shed, wed, lets) are left out on purpose: "its" is far
// more often right than "it's" would be.
const List<(String, String, double)> _contractionData = [
  ('dont', "don't", -8.0),
  ('cant', "can't", -8.0),
  ('im', "I'm", -8.0),
  ('thats', "that's", -8.0),
  ('didnt', "didn't", -8.0),
  ('isnt', "isn't", -8.0),
  ('doesnt', "doesn't", -8.8),
  ('wasnt', "wasn't", -8.8),
  ('ive', "I've", -8.8),
  ('youre', "you're", -8.8),
  ('arent', "aren't", -8.8),
  ('wont', "won't", -8.8),
  ('couldnt', "couldn't", -8.8),
  ('wouldnt', "wouldn't", -8.8),
  ('whats', "what's", -8.8),
  ('theres', "there's", -8.8),
  ('shouldnt', "shouldn't", -9.5),
  ('havent', "haven't", -9.5),
  ('hasnt', "hasn't", -9.5),
  ('hadnt', "hadn't", -9.5),
  ('werent', "weren't", -9.5),
  ('theyre', "they're", -9.5),
  ('youve', "you've", -9.5),
  ('youll', "you'll", -9.5),
  ('theyve', "they've", -9.5),
  ('theyll', "they'll", -9.5),
  ('weve', "we've", -9.5),
  ('shes', "she's", -9.5),
  ('hes', "he's", -9.5),
  ('itll', "it'll", -9.5),
  ('heres', "here's", -9.5),
  ('wheres', "where's", -9.5),
  ('whos', "who's", -9.5),
  ('hows', "how's", -9.5),
  ('couldve', "could've", -9.5),
  ('wouldve', "would've", -9.5),
  ('shouldve', "should've", -9.5),
  ('mustve', "must've", -9.5),
  ('oclock', "o'clock", -9.5),
];

final Map<String, (String, double)> _contractionsByPlain = {
  for (final (plain, full, lp) in _contractionData) plain: (full, lp),
};
final Map<String, (String, double)> _contractionsByFull = {
  for (final (_, full, lp) in _contractionData) full.toLowerCase(): (full, lp),
};

/// The plain (apostrophe-less) spellings of the contraction table.
Iterable<String> get contractionPlainForms => _contractionsByPlain.keys;

/// The contraction a writer meant by [word] (lowercase, no apostrophe):
/// `isnt` -> `isn't`, `im` -> `I'm`. Null when [word] is not a contraction
/// written without its apostrophe.
String? contractionOf(String word) => _contractionsByPlain[word.toLowerCase()]?.$1;

/// ln probability of a contraction given as its plain form (`isnt`) or with
/// the apostrophe (`isn't`), any case; null for anything else.
double? contractionLogProb(String word) {
  final w = word.toLowerCase();
  return (_contractionsByPlain[w] ?? _contractionsByFull[w])?.$2;
}

/// A dictionary word near a query, with its corpus count.
class LexiconCandidate {
  const LexiconCandidate(this.word, this.count, this.distance);

  final String word;
  final int count;

  /// [weightedEditDistance] from the query.
  final double distance;
}

class _BkNode {
  _BkNode(this.word);

  final int word;
  List<int>? distances;
  List<_BkNode>? children;
}

/// English word frequencies with fast near-neighbour lookup (a BK-tree on
/// Levenshtein distance: about 5 ms per query for 50k words, and it needs no
/// large delete index in memory).
class Lexicon {
  Lexicon._(this._words, this._counts, this._byWord, this._total, this.studyWords);

  /// Parses `word count` lines. Lines that do not parse are skipped, words
  /// are lowercased, and only the first [maxWords] distinct words are kept. A
  /// word listed twice keeps its larger count (so lists can be concatenated).
  /// The words of [studyText] (same format) are added too and marked as
  /// [studyWords].
  factory Lexicon.parse(String text, {int maxWords = 100000, String? studyText}) {
    final words = <String>[];
    final counts = <int>[];
    final index = <String, int>{};
    var total = 0;
    for (final line in text.split('\n')) {
      final sp = line.indexOf(' ');
      if (sp <= 0) continue;
      final word = line.substring(0, sp).toLowerCase();
      final count = int.tryParse(line.substring(sp + 1).trim());
      if (count == null || count <= 0) continue;
      final seen = index[word];
      if (seen != null) {
        if (count > counts[seen]) {
          total += count - counts[seen];
          counts[seen] = count;
        }
        continue;
      }
      if (words.length >= maxWords) continue;
      index[word] = words.length;
      words.add(word);
      counts.add(count);
      total += count;
    }
    if (studyText == null) return Lexicon._(words, counts, index, total, const {});
    final study = Lexicon.parse(studyText, maxWords: maxWords);
    final merged = Lexicon.parse('$text\n$studyText', maxWords: maxWords);
    return Lexicon._(merged._words, merged._counts, merged._byWord, merged._total, Set.unmodifiable(study._words));
  }

  /// Loads and parses the bundled lists: the general one (about 50k words)
  /// and the study vocabulary ([subjectWordsAsset]; skipped when [extra] is
  /// empty or the asset is missing).
  static Future<Lexicon> loadAsset({
    AssetBundle? bundle,
    String path = lexiconAsset,
    List<String> extra = const [subjectWordsAsset],
  }) async {
    final b = bundle ?? rootBundle;
    final general = await b.loadString(path);
    final study = <String>[];
    for (final e in extra) {
      try {
        study.add(await b.loadString(e));
      } catch (_) {
        // An optional list; the general one is enough to work.
      }
    }
    return Lexicon.parse(general, studyText: study.isEmpty ? null : study.join('\n'));
  }

  final List<String> _words;
  final List<int> _counts;
  final Map<String, int> _byWord;
  final int _total;
  _BkNode? _root;

  int get length => _words.length;

  /// The study vocabulary (`subject_words.txt`): words autocorrect never
  /// turns into more common ones.
  final Set<String> studyWords;

  /// Position of [word] in the list (0 = most frequent; the study words
  /// the general list lacks come after it), or null when it is not listed.
  int? rankOf(String word) => _byWord[word.toLowerCase()];

  bool contains(String word) => _byWord.containsKey(word.toLowerCase());

  /// Count of [word] in the corpus, or null when it is not in the list.
  int? countOf(String word) {
    final i = _byWord[word.toLowerCase()];
    return i == null ? null : _counts[i];
  }

  /// ln(probability) of [word]: its share of all counted words. Null when
  /// the word is not in the list.
  double? logProb(String word) {
    final c = countOf(word);
    return c == null ? null : math.log(c / _total);
  }

  /// ln(probability) of the rarest listed word.
  late final double minLogProb = _words.isEmpty
      ? math.log(1e-9)
      : math.log(_counts.reduce(math.min) / _total);

  late final List<int> _sortedCounts = (List<int>.of(_counts)..sort((a, b) => b.compareTo(a)));

  /// ln(probability) of the word at [rank] (0 = the most frequent). A rank
  /// beyond the list gives the rarest listed word. This is the reference for
  /// words the list does not know: a name or a misspelling is about as likely
  /// as a rare but real word (see `LineDecodeConfig.oovRank`).
  double logProbAtRank(int rank) {
    if (_words.isEmpty) return math.log(1e-9);
    final r = rank.clamp(0, _sortedCounts.length - 1);
    return math.log(_sortedCounts[r] / _total);
  }

  _BkNode _tree() {
    final existing = _root;
    if (existing != null) return existing;
    final root = _BkNode(0);
    for (var w = 1; w < _words.length; w++) {
      var node = root;
      while (true) {
        final d = levenshtein(_words[w], _words[node.word]);
        final ds = node.distances ??= [];
        final at = ds.indexOf(d);
        if (at < 0) {
          ds.add(d);
          (node.children ??= []).add(_BkNode(w));
          break;
        }
        node = node.children![at];
      }
    }
    return _root = root;
  }

  /// Words within [maxEdits] Levenshtein edits of [word] (lowercase), the
  /// [limit] best by weighted distance with a small bonus for frequent words.
  /// Includes [word] itself when it is listed.
  List<LexiconCandidate> candidates(String word, {int maxEdits = 2, int limit = 150}) {
    if (_words.isEmpty) return const [];
    final q = word.toLowerCase();
    final found = <LexiconCandidate>[];
    final stack = <_BkNode>[_tree()];
    while (stack.isNotEmpty) {
      final node = stack.removeLast();
      final w = _words[node.word];
      // Words whose length differs by more than maxEdits cannot match, so the
      // full distance is only needed to steer the search below.
      final d = levenshtein(q, w);
      if (d <= maxEdits) {
        found.add(LexiconCandidate(w, _counts[node.word], weightedEditDistance(q, w)));
      }
      final ds = node.distances;
      if (ds == null) continue;
      final kids = node.children!;
      for (var i = 0; i < ds.length; i++) {
        if (ds[i] >= d - maxEdits && ds[i] <= d + maxEdits) stack.add(kids[i]);
      }
    }
    double rank(LexiconCandidate c) => c.distance - 0.08 * math.log(c.count);
    found.sort((a, b) => rank(a).compareTo(rank(b)));
    return found.length > limit ? found.sublist(0, limit) : found;
  }
}
